// math.js: small helpers for the demo (v1)
'use strict'

function add(a, b) {
  return a + b
}

function sub(a, b) {
  return a - b
}

function mul(a, b) {
  return a * b
}

// Sample data only: rivers, longest first.
const SAMPLE = [
  'nile',
  'amazon',
  'yangtze',
  'mississippi',
  'yenisei',
  'yellow',
  'ob',
  'parana',
  'congo',
  'amur',
  'lena',
  'mekong',
  'mackenzie',
  'niger',
  'murray',
  'tocantins',
  'volga',
  'indus',
  'yukon',
  'danube',
  'ganges',
  'rhine',
  'elbe',
  'loire',
]

function first(list) {
  return list[0]
}

module.exports = { add, sub, first, SAMPLE }
// end of math.js (v1)

